using ChartForgeX.Interactivity.Html;
using ChartForgeX.Rendering;
using Microsoft.Playwright;
using Xunit;
using static ChartForgeX.Tests.InteractiveChartBrowser;
namespace ChartForgeX.Tests;
public sealed partial class NativeTransitionBrowserTests {
    [BrowserTheory][InlineData(false,390,false,false)][InlineData(false,760,true,true)][InlineData(true,760,true,false)][InlineData(true,390,false,true)]
    public Task ActualJointValuesAndPreserveVisibilityUseOneManagedAcceptanceAndNativeGeometryOpacityLifetime(bool bar,int width,bool dark,bool reverse) =>
        ObserveJointValuesVisibilityAsync(bar,width,dark,reverse,false);
    [BrowserTheory][InlineData(false,390,false,false)][InlineData(false,760,true,true)][InlineData(true,760,true,false)][InlineData(true,390,false,true)]
    public Task ActualRetainedRootAppearanceJointFramesKeepOneNativeEffectOrderAndAcceptedExport(bool bar,int width,bool dark,bool reverse) =>
        ObserveJointValuesVisibilityAsync(bar,width,dark,reverse,true);
    [BrowserTheory][InlineData(false,390,false,false)][InlineData(true,760,true,true)]
    public Task ActualEnabledLabelsShareTheNativeJointSeriesCompositeAndAcceptedLifetime(bool bar,int width,bool dark,bool reverse) =>
        ObserveJointValuesVisibilityAsync(bar,width,dark,reverse,false,true);
    [BrowserTheory][InlineData("stacked-bar",390,false,false,false)][InlineData("default-stacked",760,true,true,false)][InlineData("normalized-bar",390,true,false,true)][InlineData("stacked-bar",760,false,true,true)]
    public Task ActualJointStackFramesKeepNativeFullSourceTotalsGlobalAcrossTheSingleAcceptedLifetime(string variant,int width,bool dark,bool reverse,bool labels) =>
        ObserveJointValuesVisibilityAsync(true,width,dark,reverse,false,labels,variant);
    private async Task ObserveJointValuesVisibilityAsync(bool bar,int width,bool dark,bool reverse,bool retainedAppearance,bool enabledLabels=false,string? stackVariant=null) {
        if(!Enabled)return;var renderer=new HtmlInteractiveChartRenderer();
        HtmlChartSection Section(double value,bool hidden) {
            var model=stackVariant==null?NativeJointValuesVisibilityBeforeControls.Model(bar,value,width,dark).WithDataLabels(enabledLabels):NativeJointStackValueBeforeControls.Model(stackVariant,value,enabledLabels,width,dark);
            var ordinary=renderer.PrepareVisibilitySection(model,NativeJointValuesVisibilityBeforeControls.View(hidden,enabledLabels?ChartForgeX.Core.ChartVisibilityLabelLayering.GroupWithSeries:ChartForgeX.Core.ChartVisibilityLabelLayering.PreserveOverlay),configure:options=>{options.Interaction.ChartId="joint-browser";options.Interaction.Enable(ChartInteractionFeatures.Export|ChartInteractionFeatures.LegendToggles);});
            if(!retainedAppearance)return ordinary;
            // The existing internal emission boundary supplies a real native appearance endpoint without adding a public Chart effect policy.
            var drawing=ordinary.PreparedVisual.WithOutline(new ChartForgeX.Effects.VisualOutline(ChartForgeX.Primitives.ChartColor.Black,1,false))
                .WithDropShadow(new ChartForgeX.Effects.VisualDropShadow(ChartForgeX.Primitives.ChartColor.Black,2,2,0,orderedDither:false,opacity:.2));
            var options=new VisualSvgOptions(ordinary.WideEmission!.Prefix,effectProfile:VisualSvgEffectProfile.NativeFilters,effectRasterOptions:new VisualRenderOptions(supersampling:1));
            var emission=drawing.ForInteractivePngExport().ExportSvgEmission(options);
            return new HtmlChartSection(ordinary.Html.Replace(ordinary.WideEmission.Svg,emission.Svg,StringComparison.Ordinal),drawing,null,options,emission,null);
        }
        var from=Section(30,reverse);var to=Section(40,!reverse);var frames=VisualSeriesVisibilityCapture.ValueVisibilityFrames(from.PreparedVisual,to.PreparedVisual,3);var payload=renderer.PrepareNativeTransitionJson(from,to,new HtmlNativeTransitionOptions(HtmlNativeTransitionEffect.ValuesAndVisibility,3));var reset=Section(50,false);var resetPayload=reverse?null:renderer.PrepareNativeTransitionJson(to,reset,new HtmlNativeTransitionOptions(HtmlNativeTransitionEffect.ValuesAndVisibility,3));var name="joint-browser-"+bar+"-"+width+"-"+reverse+(retainedAppearance?"-retained":"")+(enabledLabels?"-labels":"")+(stackVariant==null?"":"-"+stackVariant);
        await using var session=await BrowserProofFonts.OpenAsync(Page(from),width+24,680);var page=session.Page;await ReadyAndPauseAsync(page);await page.EmulateMediaAsync(new PageEmulateMediaOptions{ReducedMotion=ReducedMotion.NoPreference});
        await page.EvaluateAsync("()=>{window.jointChart=ChartForgeXCharts.get(document.querySelector('.cfx-interactive-chart'));window.jointCalls=[];window.jointChanges=[];jointChart.root.addEventListener('cfxserieschange',event=>jointChanges.push(event.detail));jointChart.connectNative((request,signal)=>new Promise(resolve=>jointCalls.push({request,signal,resolve})),{basis:'joint-v1',axes:null,legend:true,motion:{duration:1000}});}");
        await page.Locator("[data-cfx-role=legend-item][data-cfx-series-key=delivery]").ClickAsync();await page.WaitForFunctionAsync("()=>jointCalls.length===1");var request=await page.EvaluateAsync<JsonElement>("()=>jointCalls[0].request");
        await page.EvaluateAsync("reply=>jointCalls[0].resolve(reply)",new{html=to.Html,basis="joint-v2",transition=payload});await page.Clock.RunForAsync(500);
        var observed=await page.EvaluateAsync<JsonElement>("()=>({metadata:JSON.parse(jointChart.root.dataset.cfxPreparedChart),value:jointChart.root.querySelector('.cfx-stage>svg [data-cfx-series-key=delivery][data-cfx-observation-id=current]')?.dataset.cfxY,frame:jointChart.root.querySelector('.cfx-native-motion-frame')?.outerHTML,totals:[...jointChart.root.querySelectorAll('.cfx-native-motion-frame [data-cfx-role=stack-total]')].map(row=>({x:row.dataset.cfxX,source:row.dataset.cfxSourceTotal,value:row.dataset.cfxY,opacity:row.getAttribute('opacity'),insideSeries:!!row.closest('[data-cfx-role=series-visibility]')})),changes:jointChanges,targets:jointChart.resolveTargets()})");NativeRadialValueMotionTests.Capture(from,to,frames,payload,name);NativeRadialMotionBeforeControls.Save(name+".observed.json",observed.GetRawText());NativeRadialMotionBeforeControls.Save(name+".request.json",request.GetRawText());NativeRadialMotionBeforeControls.Save(name+".bytes.json",JsonSerializer.Serialize(new{nativeTransitionUtf8Bytes=System.Text.Encoding.UTF8.GetByteCount(payload)}));
        if(Environment.GetEnvironmentVariable("CFX_BROWSER_CAPTURE_DIRECTORY") is {Length:>0} output)await page.ScreenshotAsync(new PageScreenshotOptions{Path=Path.Combine(output,name+".browser.png"),FullPage=true});
        Assert.Equal("legend",request.GetProperty("channel").GetString());Assert.Equal("joint-v1",request.GetProperty("basis").GetString());Assert.Equal("40",observed.GetProperty("value").GetString());Assert.Equal(1,observed.GetProperty("changes").GetArrayLength());Assert.Equal(reverse?0:1,observed.GetProperty("metadata").GetProperty("visibility").GetProperty("hiddenSeries").GetArrayLength());
        await NativeValueFrameBrowserProof.AssertAsync(page,"[data-cfx-role=point][data-cfx-series-key=delivery][data-cfx-observation-id=current] [data-cfx-role="+(bar?"bar":"marker")+"]",name+"-ink");
        if(stackVariant!=null){var total=Assert.Single(observed.GetProperty("totals").EnumerateArray(),row=>row.GetProperty("x").GetString()=="1");Assert.Equal("50",total.GetProperty("source").GetString());Assert.Equal(stackVariant=="normalized-bar"?"100":"50",total.GetProperty("value").GetString());Assert.False(total.GetProperty("insideSeries").GetBoolean());}
        if(enabledLabels){var labels=page.Locator(".cfx-native-motion-frame [data-cfx-role=series-visibility][data-cfx-visibility-series-key=delivery] [data-cfx-role=data-label]");Assert.True(await labels.CountAsync()>0);Assert.Equal("0.5",await page.Locator(".cfx-native-motion-frame [data-cfx-role=series-visibility][data-cfx-visibility-series-key=delivery]").GetAttributeAsync("opacity"));}
        if(retainedAppearance){Assert.Equal(2,await page.Locator(".cfx-native-motion-frame filter").CountAsync());Assert.Equal(2,await page.Locator(".cfx-native-motion-frame [filter]").CountAsync());}
        var download=await page.RunAndWaitForDownloadAsync(()=>page.Locator("[data-cfx-export=svg]").ClickAsync());var file=await download.PathAsync()??throw new InvalidOperationException("Joint accepted export missing.");var text=await File.ReadAllTextAsync(file);NativeRadialMotionBeforeControls.Save(name+".exported.svg",text);var exported=System.Xml.Linq.XDocument.Parse(text);Assert.Equal("40",exported.Descendants().Single(row=>(string?)row.Attribute("data-cfx-role")=="point"&&(string?)row.Attribute("data-cfx-series-key")=="delivery"&&(string?)row.Attribute("data-cfx-observation-id")=="current").Attribute("data-cfx-y")!.Value);Assert.Equal(0,await page.Locator(".cfx-native-motion-frame").CountAsync());if(stackVariant!=null){var total=exported.Descendants().Single(row=>(string?)row.Attribute("data-cfx-role")=="stack-total"&&(string?)row.Attribute("data-cfx-x")=="1");Assert.Equal("55",(string?)total.Attribute("data-cfx-source-total"));}if(retainedAppearance){Assert.Equal(2,exported.Descendants().Count(row=>row.Name.LocalName=="filter"));Assert.Equal(2,exported.Descendants().Count(row=>row.Attribute("filter")!=null));}
        if(!reverse){await page.Locator("[data-cfx-reset]").ClickAsync();await page.WaitForFunctionAsync("()=>jointCalls.length===2");var resetRequest=await page.EvaluateAsync<JsonElement>("()=>jointCalls[1].request");NativeRadialMotionBeforeControls.Save(name+".reset.json",resetRequest.GetRawText());Assert.Equal("reset",resetRequest.GetProperty("kind").GetString());Assert.Equal("joint-v2",resetRequest.GetProperty("basis").GetString());await page.EvaluateAsync("reply=>jointCalls[1].resolve(reply)",new{html=reset.Html,basis="joint-v3",transition=resetPayload});await page.Clock.RunForAsync(1000);}
        await page.EmulateMediaAsync(new PageEmulateMediaOptions{ReducedMotion=ReducedMotion.Reduce});await page.EvaluateAsync("()=>jointChart.dispose()");await page.Clock.RunForAsync(1500);Assert.Equal(0,await page.Locator(".cfx-native-motion-frame,[data-cfx-update-motion]").CountAsync());AssertNoConsoleErrors(session);
    }
}
